export type ParsedClaimRefundInstruction<
  TProgram extends string = typeof OBVERSE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    holder: TAccountMetas[0];
    config: TAccountMetas[1];
    startup: TAccountMetas[2];
    vaultAuthority: TAccountMetas[3];
    usdcMint: TAccountMetas[4];
    mint: TAccountMetas[5];
    holderToken: TAccountMetas[6];
    holderUsdc: TAccountMetas[7];
    refundVault: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
  };
  data: ClaimRefundInstructionData;
};

export function parseClaimRefundInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimRefundInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      holder: getNextAccount(),
      config: getNextAccount(),
      startup: getNextAccount(),
      vaultAuthority: getNextAccount(),
      usdcMint: getNextAccount(),
      mint: getNextAccount(),
      holderToken: getNextAccount(),
      holderUsdc: getNextAccount(),
      refundVault: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getClaimRefundInstructionDataDecoder().decode(instruction.data),
  };
}
